package com.bank.payout.service;

import java.util.Arrays;
import java.util.logging.Logger;

// DP framing example: state = remaining amount, transition = pick one note.
public class PayoutPlannerService {
    private static final Logger log = Logger.getLogger(PayoutPlannerService.class.getName());

    public int minNotes(int[] denominations, int amount) {
        int[] dp = new int[amount + 1];                    // dp[a] = fewest notes to make a
        Arrays.fill(dp, amount + 1);                       // amount+1 acts as infinity
        dp[0] = 0;                                          // base case: zero notes make 0
        for (int a = 1; a <= amount; a++) {
            for (int note : denominations) {               // transition: try each note last
                if (note <= a && dp[a - note] + 1 < dp[a]) {
                    dp[a] = dp[a - note] + 1;              // reuse the smaller subproblem
                }
            }
        }
        int answer = dp[amount] > amount ? -1 : dp[amount];
        log.info(() -> "Minimum notes for payout = " + answer);
        return answer;
    }
}
