package com.bank.payout;

import com.bank.payout.service.PayoutPlannerService;
import java.util.logging.Logger;

public class PayoutPlannerApplication {
    private static final Logger log = Logger.getLogger(PayoutPlannerApplication.class.getName());

    public static void main(String[] args) {
        PayoutPlannerService service = new PayoutPlannerService();
        int[] notes = {1, 2, 5};                           // note denominations
        int count = service.minNotes(notes, 11);           // payout amount = 11
        log.info(() -> "Final minimum note count = " + count);
    }
}
